      <div class="field">
        <label for="email">E-mail</label>
        <input
          id="email"
          name="email"
          type="email"
          autocomplete="username"
          placeholder="exemplo@email.com"
          required
          aria-required="true"
          aria-describedby="erro-email"
        >
        <p id="erro-email" class="error" role="alert" hidden>Informe um e-mail válido.</p>
      </div>

      <div class="field">
        <label for="senha">Senha</label>
        <div class="password-wrapper">
          <input
            id="senha"
            name="senha"
            type="password"
            autocomplete="current-password"
            required
            aria-required="true"
            aria-describedby="erro-senha"
          >
          <button type="button" class="toggle-password" aria-label="Mostrar senha">Mostrar</button>
        </div>
        <p id="erro-senha" class="error" role="alert" hidden>Informe sua senha.</p>
      </div>

      <button type="submit" class="submit-btn">Entrar</button>
    </form>

    <div class="actions">
      <a href="/recuperar">Esqueci minha senha</a>
    </div>
  </main>
