    (function () {
      var form = document.querySelector('form');
      var email = document.getElementById('email');
      var senha = document.getElementById('senha');
      var toggle = document.getElementById('toggle-senha');

      toggle.addEventListener('click', function () {
        var mostrar = senha.type === 'password';
        senha.type = mostrar ? 'text' : 'password';
        toggle.textContent = mostrar ? 'Ocultar' : 'Mostrar';
        toggle.setAttribute('aria-label', mostrar ? 'Ocultar senha' : 'Mostrar senha');
      });

      function validar(campo, erroId, mensagem) {
        var erro = document.getElementById(erroId);
        var valido = campo.checkValidity();
        if (valido) {
          erro.textContent = '';
          erro.hidden = true;
          campo.removeAttribute('aria-invalid');
        } else {
          erro.textContent = mensagem;
          erro.hidden = false;
          campo.setAttribute('aria-invalid', 'true');
        }
        return valido;
      }

      form.addEventListener('submit', function (e) {
        var emailOk = validar(email, 'erro-email', 'Informe um e-mail válido.');
        var senhaOk = validar(senha, 'erro-senha', 'Informe sua senha.');
        if (!emailOk || !senhaOk) {
          e.preventDefault();
          (emailOk ? senha : email).focus();
        }
      });
    })();
  </script>
