  </main>
  <script>
    const form = document.querySelector('form');
    const email = document.getElementById('email');
    const senha = document.getElementById('senha');
    const erroEmail = document.getElementById('erro-email');
    const erroSenha = document.getElementById('erro-senha');
    const botaoSenha = document.querySelector('.toggle-senha');

    botaoSenha.addEventListener('click', () => {
      const mostrar = senha.type === 'password';
      senha.type = mostrar ? 'text' : 'password';
      botaoSenha.textContent = mostrar ? 'Ocultar' : 'Mostrar';
      botaoSenha.setAttribute('aria-label', mostrar ? 'Ocultar senha' : 'Mostrar senha');
      botaoSenha.setAttribute('aria-pressed', String(mostrar));
    });

    function exibirErro(campo, erroEl, mensagem) {
      erroEl.textContent = mensagem;
      campo.setAttribute('aria-invalid', mensagem ? 'true' : 'false');
      return mensagem === '';
    }

    form.addEventListener('submit', (evento) => {
      let mensagemEmail = '';
      if (email.value.trim() === '') {
        mensagemEmail = 'Informe seu e-mail.';
      } else if (email.validity.typeMismatch) {
        mensagemEmail = 'Informe um e-mail válido.';
      }
      const mensagemSenha = senha.value === '' ? 'Informe sua senha.' : '';

      const emailOk = exibirErro(email, erroEmail, mensagemEmail);
      const senhaOk = exibirErro(senha, erroSenha, mensagemSenha);
      if (!emailOk || !senhaOk) {
        evento.preventDefault();
      }
    });
  </script>
