  <script>
    const form = document.querySelector('form');
    const email = document.getElementById('email');
    const senha = document.getElementById('senha');
    const erroEmail = document.getElementById('erro-email');
    const erroSenha = document.getElementById('erro-senha');
    const botaoMostrar = document.getElementById('mostrar-senha');

    function validar(campo, erro, mensagem) {
      const invalido = !campo.value.trim() || !campo.checkValidity();
      erro.textContent = invalido ? mensagem : '';
      erro.hidden = !invalido;
      campo.setAttribute('aria-invalid', String(invalido));
      return !invalido;
    }

    form.addEventListener('submit', (e) => {
      const emailOk = validar(
        email,
        erroEmail,
        email.value.trim() ? 'Informe um e-mail válido.' : 'Informe seu e-mail.'
      );
      const senhaOk = validar(senha, erroSenha, 'Informe sua senha.');

      if (!emailOk || !senhaOk) {
        e.preventDefault();
        (!emailOk ? email : senha).focus();
      }
    });

    botaoMostrar.addEventListener('click', () => {
      const mostrar = senha.type === 'password';
      senha.type = mostrar ? 'text' : 'password';
      botaoMostrar.textContent = mostrar ? 'Ocultar' : 'Mostrar';
    });
