        senha.type = mostrar ? 'text' : 'password';
        toggle.textContent = mostrar ? 'Ocultar' : 'Mostrar';
      });

      function validar(campo, erro, msg) {
        var ok = campo.checkValidity();
        erro.textContent = ok ? '' : msg;
        campo.setAttribute('aria-invalid', ok ? 'false' : 'true');
        return ok;
      }

      form.addEventListener('submit', function (e) {
        var okEmail = validar(email, erroEmail, 'Informe um e-mail válido.');
        var okSenha = validar(senha, erroSenha, senha.value ? 'A senha deve ter pelo menos 6 caracteres.' : 'Informe sua senha.');
        if (!okEmail || !okSenha) {
          e.preventDefault();
          (okEmail ? senha : email).focus();
        }
      });
    })();
