  <script>
    (function () {
      var campos = [
        { input: document.getElementById('email'), erro: document.getElementById('erro-email') },
        { input: document.getElementById('senha'), erro: document.getElementById('erro-senha') }
      ];

      campos.forEach(function (c) {
        c.input.addEventListener('invalid', function (e) {
          e.preventDefault();
          var v = c.input.validity;
          c.input.setAttribute('aria-invalid', 'true');
          c.erro.textContent = v.valueMissing
            ? 'Preencha este campo.'
            : v.typeMismatch
              ? 'Informe um e-mail válido.'
              : 'Valor inválido.';
        });
        c.input.addEventListener('input', function () {
          c.input.removeAttribute('aria-invalid');
          c.erro.textContent = '';
        });
      });

      var senha = document.getElementById('senha');
      var botao = document.querySelector('.mostrar-senha');
      botao.addEventListener('click', function () {
        var mostrar = senha.type === 'password';
        senha.type = mostrar ? 'text' : 'password';
        botao.textContent = mostrar ? 'Ocultar' : 'Mostrar';
        botao.setAttribute('aria-pressed', String(mostrar));
      });
    })();
