  <script>
    const form = document.querySelector('form');
    const email = document.getElementById('email');
    const senha = document.getElementById('senha');
    const erroEmail = document.getElementById('erro-email');
    const erroSenha = document.getElementById('erro-senha');
    const botaoMostrar = document.querySelector('.mostrar');

    function atualizarErro(campo, erro) {
      let msg = '';
      if (campo.validity.valueMissing) {
        msg = campo.id === 'email' ? 'Informe seu e-mail.' : 'Informe sua senha.';
      } else if (campo.validity.typeMismatch) {
        msg = 'Informe um e-mail válido.';
      }
      erro.textContent = msg;
      erro.hidden = msg === '';
      campo.setAttribute('aria-invalid', msg !== '' ? 'true' : 'false');
    }

    form.addEventListener('submit', function (e) {
      if (!form.checkValidity()) {
        e.preventDefault();
        atualizarErro(email, erroEmail);
        atualizarErro(senha, erroSenha);
      }
    });

    email.addEventListener('input', function () {
      atualizarErro(email, erroEmail);
    });

    senha.addEventListener('input', function () {
      atualizarErro(senha, erroSenha);
    });

    botaoMostrar.addEventListener('click', function () {
      const mostrando = senha.type === 'text';
      senha.type = mostrando ? 'password' : 'text';
      botaoMostrar.textContent = mostrando ? 'Mostrar' : 'Ocultar';
      botaoMostrar.setAttribute('aria-pressed', String(!mostrando));
    });
