  <script>
    (function () {
      var form = document.getElementById('form-login');
      var email = document.getElementById('email');
      var senha = document.getElementById('senha');
      var btnMostrar = document.getElementById('mostrar-senha');
      var erroEmail = document.getElementById('erro-email');
      var erroSenha = document.getElementById('erro-senha');

      btnMostrar.addEventListener('click', function () {
        var mostrar = senha.type === 'password';
        senha.type = mostrar ? 'text' : 'password';
        btnMostrar.textContent = mostrar ? 'Ocultar' : 'Mostrar';
        btnMostrar.setAttribute('aria-label', mostrar ? 'Ocultar senha' : 'Mostrar senha');
      });

      function mostrarErro(campo, p, msg) {
        campo.setAttribute('aria-invalid', 'true');
        p.textContent = msg;
        p.hidden = false;
      }

      function limparErro(campo, p) {
        campo.removeAttribute('aria-invalid');
        p.textContent = '';
        p.hidden = true;
      }

      form.addEventListener('submit', function (e) {
        var ok = true;

        if (!email.value.trim() || !email.checkValidity()) {
          mostrarErro(email, erroEmail, 'Informe um e-mail válido, como nome@exemplo.com.');
          ok = false;
        } else {
          limparErro(email, erroEmail);
        }

        if (!senha.value) {
          mostrarErro(senha, erroSenha, 'Informe sua senha.');
          ok = false;
        } else {
          limparErro(senha, erroSenha);
        }

        if (!ok) {
          e.preventDefault();
        }
      });
    })();
