  <script>
    const form = document.querySelector('form');
    const email = document.getElementById('email');
    const senha = document.getElementById('senha');
    const emailErro = document.getElementById('email-erro');
    const senhaErro = document.getElementById('senha-erro');
    const toggle = document.querySelector('.toggle-senha');

    toggle.addEventListener('click', () => {
      const mostrar = senha.type === 'password';
      senha.type = mostrar ? 'text' : 'password';
      toggle.textContent = mostrar ? 'Ocultar' : 'Mostrar';
      toggle.setAttribute('aria-label', mostrar ? 'Ocultar senha' : 'Mostrar senha');
    });

    function validarCampo(campo, erro, mensagem) {
      const ok = campo.value.trim() !== '' && campo.checkValidity();
      erro.textContent = ok ? '' : mensagem;
      erro.hidden = ok;
      campo.setAttribute('aria-invalid', String(!ok));
      return ok;
    }

    form.addEventListener('submit', (e) => {
      e.preventDefault();
      const emailOk = validarCampo(email, emailErro, 'Informe um e-mail válido.');
      const senhaOk = validarCampo(senha, senhaErro, 'Informe sua senha.');
      if (emailOk && senhaOk) {
        form.submit();
      }
    });
  </script>
