  <script>
    const form = document.querySelector('form');
    const email = document.getElementById('email');
    const senha = document.getElementById('senha');
    const toggle = document.querySelector('.toggle-password');

    toggle.addEventListener('click', () => {
      const mostrar = senha.type === 'password';
      senha.type = mostrar ? 'text' : 'password';
      toggle.textContent = mostrar ? 'Ocultar' : 'Mostrar';
    });

    form.addEventListener('submit', (e) => {
      const emailOk = email.checkValidity();
      const senhaOk = senha.value.length >= 6;

      email.closest('.field').classList.toggle('invalid', !emailOk);
      email.setAttribute('aria-invalid', String(!emailOk));
      senha.closest('.field').classList.toggle('invalid', !senhaOk);
      senha.setAttribute('aria-invalid', String(!senhaOk));

      if (!emailOk || !senhaOk) e.preventDefault();
    });
  </script>
