        toggle.setAttribute('aria-label', mostrar ? 'Ocultar senha' : 'Mostrar senha');
      });

      form.addEventListener('submit', function (e) {
        var msgEmail = '';
        if (!email.value.trim()) {
          msgEmail = 'Informe seu e-mail.';
        } else if (!email.validity.valid) {
          msgEmail = 'Informe um e-mail válido.';
        }
        var msgSenha = senha.value ? '' : 'Informe sua senha.';

        marcar(email, errEmail, msgEmail);
        marcar(senha, errSenha, msgSenha);

        if (msgEmail || msgSenha) {
          e.preventDefault();
          (msgEmail ? email : senha).focus();
        }
      });
    })();
