  <script>
    (function () {
      var form = document.querySelector('form');
      var email = document.getElementById('email');
      var senha = document.getElementById('senha');
      var btnToggle = document.querySelector('.toggle-senha');
      var erroEmail = document.getElementById('erro-email');
      var erroSenha = document.getElementById('erro-senha');

      btnToggle.addEventListener('click', function () {
        var mostrar = senha.type === 'password';
        senha.type = mostrar ? 'text' : 'password';
        btnToggle.textContent = mostrar ? 'Ocultar' : 'Mostrar';
      });

      function mostrarErro(campo, el, msg) {
        el.textContent = msg;
        el.hidden = false;
        campo.setAttribute('aria-invalid', 'true');
      }

      function limparErro(campo, el) {
        el.textContent = '';
        el.hidden = true;
        campo.removeAttribute('aria-invalid');
      }

      form.addEventListener('submit', function (e) {
        var emailOk = true;
        var senhaOk = true;

        if (!email.value.trim()) {
          mostrarErro(email, erroEmail, 'Informe seu e-mail.');
          emailOk = false;
        } else if (!email.validity.valid) {
          mostrarErro(email, erroEmail, 'Informe um e-mail válido, por exemplo: seu.nome@empresa.com.br.');
          emailOk = false;
        } else {
          limparErro(email, erroEmail);
        }

        if (!senha.value) {
          mostrarErro(senha, erroSenha, 'Informe sua senha.');
          senhaOk = false;
        } else {
          limparErro(senha, erroSenha);
        }

        if (!emailOk || !senhaOk) {
          e.preventDefault();
          (emailOk ? senha : email).focus();
        }
      });
    })();
  </script>
</body>
