  <script>
    (function () {
      var form = document.querySelector('form');
      var email = document.getElementById('email');
      var senha = document.getElementById('senha');
      var erroEmail = document.getElementById('erro-email');
      var erroSenha = document.getElementById('erro-senha');
      var toggle = document.querySelector('.toggle-senha');

      toggle.addEventListener('click', function () {
        var mostrar = senha.type === 'password';
        senha.type = mostrar ? 'text' : 'password';
        toggle.textContent = mostrar ? 'Ocultar' : 'Mostrar';
      });

      form.addEventListener('submit', function (e) {
        erroEmail.textContent = '';
        erroSenha.textContent = '';
        email.removeAttribute('aria-invalid');
        senha.removeAttribute('aria-invalid');

        if (!email.value.trim()) {
          erroEmail.textContent = 'Informe seu e-mail.';
        } else if (email.validity.typeMismatch) {
          erroEmail.textContent = 'Informe um e-mail válido, como nome@exemplo.com.';
        }

        if (!senha.value) {
          erroSenha.textContent = 'Informe sua senha.';
        }

        if (erroEmail.textContent || erroSenha.textContent) {
          e.preventDefault();
          if (erroEmail.textContent) {
            email.setAttribute('aria-invalid', 'true');
            email.focus();
          } else {
            senha.focus();
          }
          if (erroSenha.textContent) {
            senha.setAttribute('aria-invalid', 'true');
          }
        }
      });
    })();
  </script>
