  <script>
    const form = document.querySelector("form");
    const email = document.getElementById("email");
    const senha = document.getElementById("senha");
    const erroEmail = document.getElementById("erro-email");
    const erroSenha = document.getElementById("erro-senha");
    const botaoSenha = document.querySelector(".mostrar-senha");

    function marcarErro(campo, erroEl, mensagem) {
      erroEl.textContent = mensagem;
      if (mensagem) {
        campo.setAttribute("aria-invalid", "true");
      } else {
        campo.removeAttribute("aria-invalid");
      }
    }

    form.addEventListener("submit", (e) => {
      const invalidos = [];

      if (!email.value.trim()) {
        marcarErro(email, erroEmail, "Informe seu e-mail.");
        invalidos.push(email);
      } else if (!email.checkValidity()) {
        marcarErro(email, erroEmail, "Informe um e-mail válido, como voce@empresa.com.br.");
        invalidos.push(email);
      } else {
        marcarErro(email, erroEmail, "");
      }

      if (!senha.value) {
        marcarErro(senha, erroSenha, "Informe sua senha.");
        invalidos.push(senha);
      } else {
        marcarErro(senha, erroSenha, "");
      }

      if (invalidos.length) {
        e.preventDefault();
        invalidos[0].focus();
      }
    });

    botaoSenha.addEventListener("click", () => {
      const mostrar = senha.type === "password";
      senha.type = mostrar ? "text" : "password";
      botaoSenha.textContent = mostrar ? "Ocultar" : "Mostrar";
      botaoSenha.setAttribute("aria-label", mostrar ? "Ocultar senha" : "Mostrar senha");
    });
  </script>
</body>
