  <script>
    (function () {
      var form = document.querySelector('form');
      var email = document.getElementById('email');
      var senha = document.getElementById('senha');
      var botaoSenha = document.getElementById('alternar-senha');
      var erroEmail = document.getElementById('erro-email');
      var erroSenha = document.getElementById('erro-senha');

      function marcar(campo, erro, mensagem) {
        var valido = campo.checkValidity() && campo.value.trim() !== '';
        erro.textContent = mensagem;
        erro.hidden = valido;
        campo.setAttribute('aria-invalid', String(!valido));
        return valido;
      }

      form.addEventListener('submit', function (e) {
        var emailOk = marcar(email, erroEmail, 'Informe um e-mail válido.');
        var senhaOk = marcar(senha, erroSenha, 'Informe sua senha.');
        if (!emailOk || !senhaOk) {
          e.preventDefault();
          (emailOk ? senha : email).focus();
        }
      });

      botaoSenha.addEventListener('click', function () {
        var mostrar = senha.type === 'password';
        senha.type = mostrar ? 'text' : 'password';
        botaoSenha.textContent = mostrar ? 'Ocultar' : 'Mostrar';
      });
    })();
