  <script>
    (function () {
      var form = document.querySelector('form');
      var email = document.getElementById('email');
      var senha = document.getElementById('senha');
      var erroEmail = document.getElementById('erro-email');
      var erroSenha = document.getElementById('erro-senha');
      var botaoMostrar = document.getElementById('alternar-senha');

      function mostrarErro(campo, elemento, mensagem) {
        if (mensagem) {
          elemento.textContent = mensagem;
          elemento.hidden = false;
          campo.setAttribute('aria-invalid', 'true');
        } else {
          elemento.textContent = '';
          elemento.hidden = true;
          campo.removeAttribute('aria-invalid');
        }
      }

      form.addEventListener('submit', function (evento) {
        var msgEmail = '';
        var msgSenha = '';

        if (email.value.trim() === '') {
          msgEmail = 'Informe seu e-mail.';
        } else if (!email.checkValidity()) {
          msgEmail = 'Informe um e-mail válido, como nome@exemplo.com.';
        }

        if (senha.value === '') {
          msgSenha = 'Informe sua senha.';
        }

        mostrarErro(email, erroEmail, msgEmail);
        mostrarErro(senha, erroSenha, msgSenha);

        if (msgEmail || msgSenha) {
          evento.preventDefault();
        }
      });

      botaoMostrar.addEventListener('click', function () {
        var mostrando = senha.type === 'text';
        senha.type = mostrando ? 'password' : 'text';
        botaoMostrar.textContent = mostrando ? 'Mostrar' : 'Ocultar';
      });
    })();
  </script>
