<!DOCTYPE html>
<html lang="pt-BR">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Login - Clube de Xadrez</title>
  <style>
    * {
      box-sizing: border-box;
      margin: 0;
      padding: 0;
    }

    body {
      font-family: Arial, Helvetica, sans-serif;
      min-height: 100vh;
      display: flex;
      align-items: center;
      justify-content: center;
      background: linear-gradient(135deg, #2c2c2c 0%, #4a3728 100%);
      background-image:
        linear-gradient(45deg, rgba(255,255,255,0.03) 25%, transparent 25%),
        linear-gradient(-45deg, rgba(255,255,255,0.03) 25%, transparent 25%),
        linear-gradient(45deg, transparent 75%, rgba(255,255,255,0.03) 75%),
        linear-gradient(-45deg, transparent 75%, rgba(255,255,255,0.03) 75%);
      background-size: 40px 40px;
      padding: 20px;
    }

    .card {
      background: #fdfaf4;
      width: 100%;
      max-width: 400px;
      border-radius: 12px;
      box-shadow: 0 10px 30px rgba(0, 0, 0, 0.4);
      padding: 40px 32px;
      border-top: 6px solid #8b5a2b;
    }

    .logo {
      text-align: center;
      margin-bottom: 24px;
    }

    .logo-icon {
      font-size: 48px;
      color: #3b2a1a;
      line-height: 1;
    }

    .titulo {
      text-align: center;
      color: #3b2a1a;
      font-size: 24px;
      margin-bottom: 6px;
    }

    .subtitulo {
      text-align: center;
      color: #7a6a5a;
      font-size: 14px;
      margin-bottom: 28px;
    }

    .campo {
      margin-bottom: 20px;
    }

    label {
      display: block;
      color: #3b2a1a;
      font-size: 14px;
      font-weight: bold;
      margin-bottom: 6px;
    }

    input[type="email"],
    input[type="password"] {
      width: 100%;
      padding: 12px 14px;
      font-size: 15px;
      border: 1px solid #c9b79c;
      border-radius: 8px;
      background: #ffffff;
      color: #3b2a1a;
      outline: none;
      transition: border-color 0.2s, box-shadow 0.2s;
    }

    input[type="email"]:focus,
    input[type="password"]:focus {
      border-color: #8b5a2b;
      box-shadow: 0 0 0 3px rgba(139, 90, 43, 0.2);
    }

    .botao-entrar {
      width: 100%;
      padding: 13px;
      font-size: 16px;
      font-weight: bold;
      color: #ffffff;
      background: #8b5a2b;
      border: none;
      border-radius: 8px;
      cursor: pointer;
      transition: background 0.2s, transform 0.1s;
      margin-top: 8px;
    }

    .botao-entrar:hover {
      background: #6f4520;
    }

    .botao-entrar:active {
      transform: scale(0.98);
    }

    .botao-entrar:focus-visible {
      outline: 3px solid rgba(139, 90, 43, 0.4);
      outline-offset: 2px;
    }

    .rodape {
      text-align: center;
      margin-top: 24px;
      font-size: 13px;
      color: #7a6a5a;
    }

    .rodape a {
      color: #8b5a2b;
      text-decoration: none;
      font-weight: bold;
    }

    .rodape a:hover {
      text-decoration: underline;
    }

    @media (max-width: 480px) {
      .card {
        padding: 32px 22px;
      }
    }
  </style>
</head>
<body>
  <main class="card">
    <header class="logo">
      <div class="logo-icon" aria-hidden="true">&#9822;</div>
    </header>

    <h1 class="titulo">Clube de Xadrez</h1>
    <p class="subtitulo">Entre com sua conta de sócio para se inscrever nos torneios</p>

    <form action="#" method="post">
      <div class="campo">
        <label for="email">E-mail</label>
        <input type="email" id="email" name="email" placeholder="seuemail@exemplo.com" required autocomplete="email">
      </div>

      <div class="campo">
        <label for="senha">Senha</label>
