  </main>
  <script>
    (function () {
      var form = document.querySelector('form');
      var email = document.getElementById('email');
      var senha = document.getElementById('senha');
      var botao = document.querySelector('.mostrar-senha');
      var erroEmail = document.getElementById('erro-email');
      var erroSenha = document.getElementById('erro-senha');

      botao.addEventListener('click', function () {
        var mostrar = senha.type === 'password';
        senha.type = mostrar ? 'text' : 'password';
        botao.textContent = mostrar ? 'Ocultar' : 'Mostrar';
      });

      function validar(campo, erro, msgVazio, msgInvalido) {
        var msg = '';
        if (campo.validity.valueMissing) {
          msg = msgVazio;
        } else if (campo.validity.typeMismatch) {
          msg = msgInvalido;
        }
        campo.setAttribute('aria-invalid', msg ? 'true' : 'false');
        erro.textContent = msg;
        return msg === '';
      }

      form.addEventListener('submit', function (e) {
        var emailOk = validar(email, erroEmail, 'Informe seu e-mail.', 'Informe um e-mail válido.');
        var senhaOk = validar(senha, erroSenha, 'Informe sua senha.', '');
        if (!emailOk || !senhaOk) {
          e.preventDefault();
        }
      });
    })();
  </script>
